INSERT INTO "config_values" ("key", "scope_level", "value", "effective_at", "status", "reason", "decided_at") VALUES
  ('contract.loan_template', 'global', $legal${"title": "قرارداد اعطای وام", "sample": true, "lender": {"entityId": "aramesh", "name": "شرکت آرامش ثروت"}, "body": "# پیش‌نویس — در انتظار تأیید حقوقی\n\nاین متن از نمونه «قرارداد اعطای وام» و فرم «شرایط و تعهدات» کارفرما ساخته شده است و تا تأیید مشاور حقوقی برای استفاده نیست.\n\n# طرفین\n\nاین قرارداد به شماره {{contract.number}} در تاریخ {{contract.date}} میان {{lender.name}} به‌عنوان وام‌دهنده و {{borrower.name}} به شماره همراه {{borrower.mobile}} به‌عنوان وام‌گیرنده بسته می‌شود.\n\nضامن یا ضامنان: {{guarantors.names}}\n\n# موضوع و مبلغ\n\nوام‌دهنده مبلغ {{loan.amount}} را برای هزینه درمان وام‌گیرنده، در قالب {{plan.title}}، از راه کیف اعتبار در اختیار مرکز درمانی می‌گذارد. پیش‌پرداخت {{downPayment.amount}} و هزینه تشکیل پرونده {{originationFee.amount}} است. کارمزد طرح {{planFee.amount}} و جمع اقساط {{totalObligation.amount}} است. {{amounts.roundingNote}}\n\n# اقساط\n\nبازپرداخت در {{installments.count}} قسط ماهانه است. سررسیدها از روز واریز وام حساب می‌شوند و جدول زیر پیش‌نمایش است:\n\n{{installments.table}}\n\n# انصراف\n\nدر انصراف پس از واریز، وام‌گیرنده {{cancellation.penaltyPercent}} مبلغ مصوب وام را به‌عنوان خسارت می‌پردازد.\n\n# مشخصات وام‌گیرنده\n\nنام: .................... نام خانوادگی: .................... نام پدر: .................... شماره شناسنامه: .................... تاریخ تولد: .................... صادره: ....................\n\nکدملی: .................... شغل: .................... شماره حساب قرض‌الحسنه: .................... تلفن منزل: ....................\n\nنشانی منزل: .................... کد پستی: .................... تلفن محل کار: ....................\n\nنشانی محل کار: .................... کد پستی: .................... همراه: ....................\n\n# مشخصات ضامن ۱\n\nنام: .................... نام خانوادگی: .................... نام پدر: .................... شماره شناسنامه: .................... تاریخ تولد: .................... صادره: ....................\n\nکدملی: .................... شغل: .................... تلفن منزل: ....................\n\nنشانی منزل: .................... کد پستی: .................... تلفن محل کار: ....................\n\nنشانی محل کار: .................... کد پستی: .................... همراه: ....................\n\n# مشخصات ضامن ۲\n\nنام: .................... نام خانوادگی: .................... نام پدر: .................... شماره شناسنامه: .................... تاریخ تولد: .................... صادره: ....................\n\nکدملی: .................... شغل: .................... تلفن منزل: ....................\n\nنشانی منزل: .................... کد پستی: .................... تلفن محل کار: ....................\n\nنشانی محل کار: .................... کد پستی: .................... همراه: ....................\n\n# مشخصات ضامن ۳\n\nنام: .................... نام خانوادگی: .................... نام پدر: .................... شماره شناسنامه: .................... تاریخ تولد: .................... صادره: ....................\n\nکدملی: .................... شغل: .................... تلفن منزل: ....................\n\nنشانی منزل: .................... کد پستی: .................... تلفن محل کار: ....................\n\nنشانی محل کار: .................... کد پستی: .................... همراه: ....................\n\n# تعهد و وکالتنامه وام‌گیرنده و ضامن‌ها\n\nاینجانبان با امضاء این برگه شرعاً و قانوناً پرداخت اصل وام و کلیه هزینه‌های مربوط به آن را منفرداً و متضامناً قبول کرده و در صورتی که حداکثر دو قسط از اقساط وام مذکور در سررسید مقرر پرداخت نگردد، صندوق را ضمن عقد خارج و لازم با حق توکیل غیر و سلب حق عزل از خود و ضامنین و وکیل به صورت بلاعزل وکیل قرار می‌دهیم که کلیه دیون را به دین حال تبدیل نموده و از موجودی هر یک از حساب‌های اینجانبان در صندوق برداشت نماید و یا از اسناد وثیقه نزد صندوق استیفاء نماید و همچنین متعهد می‌شویم که حداکثر تا یک ماه پس از تسویه وام، اسناد وثیقه را از صندوق دریافت نمائیم. در غیر اینصورت به صندوق وکالت می‌دهیم که اسناد وثیقه را امحاء نماید و حق هر گونه مطالبه اسناد یا اعتراضی را از خود سلب می‌نمائیم و با امضاء این برگه کلیه شرایط و ضوابط و مقرراتی را که در محل صندوق نصب است را مطالعه نموده و قبول می‌نمائیم.\n\nامضاء متقاضی: .................... امضاء ضامن ۱: .................... امضاء ضامن ۲: .................... امضاء ضامن ۳: ....................\n\n# مشخصات معرف\n\nاینجانب: .................... فرزند: .................... شماره شناسنامه: .................... صادره از: .................... متولد: .................... شغل: ....................\n\nآدرس محل کار و شماره تلفن: ....................\n\n(منزل مسکونی): ....................\n\nاعلام می‌دارم صحت نیاز متقاضی وام فوق الذکر مورد تایید اینجانب بوده و شرعاً وظیفه خود می‌دانم و متعهد میشوم در صورت عدم وصول اقساط وام نامبرده فوق از هر گونه همکاری با صندوق جهت وصول اقساط معوق دریغ ننمایم.\n\nامضا و مهر معرفی کننده: ....................\n\n# پیوست: روند کار، شرایط و تعهدات\n\nهوالشافی\n\nضمن خیر مقدم و آرزوی سلامتی برای شما عزیزان، توجه شما را به روند کار جلب می‌نماییم:\n\n۱- کارشناسان شرکت موظف هستند پس از اطلاع از نوع درمان مورد نیاز متقاضیان/بیماران، لیست مراکز و پزشکان طرف قرارداد شرکت را در اختیار آنها قرار دهند.\n\n۲- متقاضیان می‌تواند در صورت تمایل هر یک از افراد یا مراکز لیست مذکور را انتخاب نماید.\n\n۳- پس از تکمیل فرایند ثبت نام، معرفی نامه ی معاینه در اختیار متقاضی قرار خواهد گرفت.\n\n۴- متقاضی برای انجام معاینات و تعیین هزینه درمان مرجع درمان انتخابی خود باید معرفی نامه دریافتی را ارائه نماید.\n\n۵- پس از تکمیل معاینات و دریافت صورت حساب، متقاضی برای دریافت وام به همراه ضامن به شرکت مراجعه می‌کند.\n\n۶- کارشناس بانک با توجه به مبلغ صورتحساب و شرایط متقاضی، مناسب‌ترین طرح وام را با مشورت خود فرد به وی پیشنهاد می‌نماید.\n\n۷- پس از واریز وام، آموزش نحوه پرداخت اقساط و دریافت نام کاربری و رمز عبور سامانه اعتباری مراجعه و پس از فعال سازی سامانه اعتباری جهت دریافت خدمات به مرکز درمانی مراجعه نمایند. متقاضیان موظف هستند پس از تکمیل پرونده و گذشت ۱۵ روز کاری با کارشناس مربوطه ارتباط برقرار نماید و شخصا پیگیر دریافت خدمات خود باشد. لذا شرکت هیچگونه مسئولیتی نسبت به سهل انگاری و تاخیر در دریافت خدمات متقاضی ندارد.\n\n۸- به طور معمول مدت زمان کل این فرایند حدود ۲۰ روز کاری (حدوداً یک ماه) می‌باشد.\n\nشرایط و تعهدات:\n\n۱) به دلیل رزرو نوبت برای متقاضی و همچنین محدودیت ظرفیت معاینات، مبلغ ویزیت مراکز طرف قرارداد در شرکت دریافت می‌گردد. بدیهی است پس از دریافت این مبلغ، معرفی‌نامه معاینه برای متقاضی ارسال خواهد شد و متقاضی در زمان مراجعه به مراکز درمان با ارائه این معرفی نامه هزینه‌ای بابت ویزیت پرداخت نخواهد کرد.\n\n۲) به دلیل رزرو نوبت برای متقاضی، معرفی نامه دارای روز و ساعت مشخص بوده و متقاضی موظف است پس از هماهنگی با مرکز درمان در زمان قید شده در معرفی نامه به آن مرکز مراجعه نماید. لازم به ذکر است معرفی‌نامه فقط برای زمان خود معتبر بوده و پس از آن فاقد اعتبار می‌باشد و پس از تعیین وقت و صدور معرفی نامه امکان عودت هزینه ویزیت و تشکیل پرونده امکان پذیر نمی باشد.\n\n۳) پیش فاکتور مرکز درمانی یکی از مدارک لازم برای دریافت وام بوده و بدون پیش فاکتور امکان پرداخت وام وجود ندارد و دریافت پیش فاکتور بر عهده شخص متقاضی می باشد و شرکت هیچگونه اظهارنظر در صدور و دریافت آن ندارد.\n\n۴) با توجه به اینکه پس از ۴۵ روز امکان تغییر در طرح درمان، تعرفه و ... از طرف مرکز درمان وجود دارد و همچنین به دلیل متغیر بودن نرخ ارز، قیمت خدمات و مواد مصرفی افزایش پیدا می‌کند. لذا پس از این زمان در صورت تمایل برای دریافت وام، متقاضی می‌بایست مجدداً صورتحساب جدید دریافت نماید.\n\n۵) با توجه به اینکه در حال حاضر شرکت دارای طرح‌های مختلف وام می‌باشد، کارشناس بانک با در نظر گرفتن شرایط متقاضی از جمله مدت بازپرداخت، میزان مسدودی، همچنین نوع ضامن ارائه شده و ... با مشورت خود فرد، مناسب‌ترین طرح وام را برای وی مشخص می‌نماید.\n\n۶) با توجه به اینکه این وام صرفاً جهت موارد درمانی مصوب گردیده، از پرداخت این مبلغ یا بخشی از این مبلغ در هر زمان به صورت نقدی یا واریز به حساب شخصی متقاضی و یا ثالث معذور می‌باشیم.\n\n۷) به دلیل اینکه صورت حساب دارای اعتبار ۴۵ روزه می باشد و بعد از این مدت صورت حساب فاقد اعتبار می‌باشد، متقاضی تا پایان یک ماه از صدور صورت حساب، زمان برای تکمیل پرونده در بانک را دارد.\n\n۸) مدت اعتبار استفاده خدمات از تاریخ آزادسازی وام به مدت ۴ ماه می‌باشد و در صورت انقضای این مدت، هیچگونه مسئولیتی به عهده شرکت و مراجع درمان در مورد ارائه خدمات با قیمت اعلام شده از قبل وجود ندارد.\n\n۹) شروع عملیات دریافت وام پس از درخواست کتبی و اعتبار سنجی مالی از واحد حقوقی و واحد بانک و صندوق امکان پذیر می‌باشد.\n\n۱۰) هرگونه عدم دریافت خدمات درمانی از لحاظ کمی و کیفی از طرف مراجع درمانی از جمله (کنسلی و یا به تاخیر افتادن تاریخ عمل، تاخیر در دریافت خدمات درمانی، ...) مجوز عدم پرداخت اقساط از طرف وام گیرنده و خدمات گیرنده نمی باشد.\n\n۱۱) ضمانت اجرای معوق شدن اقساط وام:\n\nالف) مسدود شدن دریافت خدمات تا زمان مرتفع شدن معوقات.\n\nب) مراجع مالی این اختیار را دارند که بدون اعلام قبلی با اجرای ضمانتنامه‌های توثیق شده طلب خود را وصول کرده و هیچ گونه مسئولیتی متوجه شرکت نمی‌باشد.\n\nج) در صورت معوق شدن اقساط (وام گیرنده، ضامن و دریافت کننده خدمات) متضامناً متعهد و ضامن پرداخت اصل و سود وام و جبران خسارات وارده می باشد.\n\nد) محدود یا ممنوع شدن بیمار/وام گیرنده/ضامن/دریافت کننده خدمات این فرم در دریافت وام و خدمات از مراجع طرف قرارداد شرکت.\n\n۱۲) آزاد سازی مسدودی/ وجه الضمان بعد از سررسید آخر اقساط و تسویه وام و با درخواست کتبی وام گیرنده امکان پذیر است و در صورت تاخیر در پرداخت اقساط با تاخیر آزاد می گردد و تحت هیچ شرایطی امکان تهاتر مسدودی با اقساط وام وجود ندارد.\n\n* پس از تکمیل پرونده و ارسال مدارک به صندوق، امکان انصراف، عودت کل یا بخشی از مبلغ وام وجود ندارد *\n\nلازم به ذکر است انصراف از دریافت وام در شرایط خاص با درخواست کتبی وام گیرنده و با تائید شرکت و پرداخت ۱۸٪ مبلغ وام به عنوان خسارت کنسلی امتیاز وام امکان پذیر است.\n\nاینجانب بیمار/وام گیرنده/دریافت کننده خدمات با مطالعه این فرم، اطلاع و آگاهی کامل از مفاد آن بدست آورده و در صحت و سلامت عقل، کلیه موارد مندرج در این فرم را گواهی و ضمانت و تائید و امضاء نموده و کلیه تبعات عدم اجرای تعهدات را می‌پذیریم.\n\nامضا و اثر انگشت وام گیرنده/بیمار/دریافت کننده خدمات: ....................\n\n# پذیرش\n\nوام‌گیرنده و ضامنان این قرارداد را با کد یک‌بارمصرف می‌پذیرند و نسخه امضاشده فیزیکی آن را نیز تحویل می‌دهند."}$legal$::jsonb, now(), 'approved',
   'پیش‌نویس از نمونه قرارداد و فرم تعهدات کارفرما، در انتظار تأیید حقوقی (مهاجرت 0098)', now()),
  ('credit.consent_text', 'global', $legal${"text": "پیش‌نویس — در انتظار تأیید حقوقی: اینجانب با بررسی اطلاعات اعتباری، شغلی و بانکی خود برای این پرونده اعتباری موافقت می‌کنم، و «روند کار، شرایط و تعهدات» پیوست قرارداد اعطای وام را خوانده‌ام. متن نهایی را مشاور حقوقی شرکت تأیید می‌کند."}$legal$::jsonb, now(), 'approved',
   'پیش‌نویس، در انتظار تأیید حقوقی (مهاجرت 0098)', now());
